import cv2,numpy as np
from PIL import Image
T=cv2.imread('/app/target.png',0)<128
C=cv2.imread('/app/output/canvas.png',0)<133
best=(0,None,None,None)
for dy in range(-23,24):
 for dx in range(-23,24):
  S=np.zeros_like(C);y0=max(0,dy);y1=min(1024,1024+dy);x0=max(0,dx);x1=min(1024,1024+dx)
  S[y0:y1,x0:x1]=C[y0-dy:y1-dy,x0-dx:x1-dx]
  i=np.logical_and(T,S).sum();u=np.logical_or(T,S).sum();val=i/u
  if val>best[0]:best=(val,dx,dy,S)
S=best[3]; inter=(T&S).sum();print('areas',T.sum(),C.sum(),'best',best[:3],'precision',inter/S.sum(),'recall',inter/T.sum())
dtT=cv2.distanceTransform((~T).astype(np.uint8),cv2.DIST_L2,5);dtS=cv2.distanceTransform((~S).astype(np.uint8),cv2.DIST_L2,5)
bt=cv2.morphologyEx(T.astype(np.uint8),cv2.MORPH_GRADIENT,np.ones((3,3),np.uint8))>0;bs=cv2.morphologyEx(S.astype(np.uint8),cv2.MORPH_GRADIENT,np.ones((3,3),np.uint8))>0
p=(dtT[bs]<=4.5).sum()/bs.sum();r=(dtS[bt]<=4.5).sum()/bt.sum();print('boundary F',2*p*r/(p+r),'p/r',p,r,'stray',np.logical_and(S,dtT>4.5).sum()/T.sum())
out=np.zeros((1024,1024,3),np.uint8);out[T&S]=[20,20,20];out[T&~S]=[255,0,0];out[~T&S]=[0,80,255];out[~T&~S]=[247,244,236];Image.fromarray(out).save('/app/output/compare.png')
